function cities(): array
{
    static $c = null;
    return $c ??= db()->query('SELECT * FROM cities ORDER BY name_en')->fetchAll();
}

function city_name(?array $row): string
{
    if (!$row) {
        return '';
    }
    $name = match (lang()) {
        'ckb' => $row['city_ku'] ?? $row['name_ku'] ?? '',
        'ar' => $row['city_ar'] ?? $row['name_ar'] ?? '',
        default => '',
    };
    return $name !== '' ? $name : ($row['city_en'] ?? $row['name_en'] ?? '');
}

function price_label(array $p): string
{
    $s = money((int) $p['price'], $p['currency'] ?? 'USD');
    if ($p['purpose'] === 'rent' && !empty($p['rent_period'])) {
        $s .= ' / ' . t('period_' . $p['rent_period']);
    }
    return $s;
}

function favorite_ids(): array
{
    static $ids = null;
    if ($ids !== null) {
        return $ids;
    }
    $u = current_user();
    if (!$u) {
        return $ids = [];
    }
    $stmt = db()->prepare('SELECT property_id FROM favorites WHERE user_id = ?');
    $stmt->execute([$u['id']]);
    return $ids = array_map('intval', $stmt->fetchAll(PDO::FETCH_COLUMN));
}

/** Simple pagination metadata */
function paginate(int $total, int $perPage, int $page): array
{
    $pages = max(1, (int) ceil($total / $perPage));
    $page = min(max(1, $page), $pages);
    return ['total' => $total, 'per_page' => $perPage, 'page' => $page, 'pages' => $pages, 'offset' => ($page - 1) * $perPage];
}

/**
 * Generic per-IP + endpoint rate limit. Limits are deliberately GENEROUS: Kurdistan/Iraq mobile users sit behind
 * carrier-grade NAT, so many real people share one IP. Honeypot + minimum fill time stop bots; per-account
 * limits protect logins. Responds 429 + Retry-After when exceeded.
 */
function rate_limit(string $endpoint, int $max, int $windowSec): void
{
    $now = time();
    $k = $endpoint . ':' . client_ip();
    if (random_int(1, 50) === 1) {
        db()->prepare('DELETE FROM hits WHERE t < ?')->execute([$now - 86400]);
    }
    $c = db()->prepare('SELECT COUNT(*) FROM hits WHERE k = ? AND t >= ?');
    $c->execute([$k, $now - $windowSec]);
    if ((int) $c->fetchColumn() >= $max) {
        header('Retry-After: ' . $windowSec);
        if (wants_json()) {
            json_out(['ok' => false, 'error' => t('err_429')], 429);
        }
        abort(429);
    }
    db()->prepare('INSERT INTO hits (k, t) VALUES (?, ?)')->execute([$k, $now]);
}

/* Minimum fill time for public forms: a signed timestamp; bots that submit instantly are ignored. */
function form_secret(): string
{
    return hash('sha256', 'aqarat-form|' . vapid_keys()['private_pem']);
}

function form_time_field(): string
{
    $t = (string) time();
    return '<input type="hidden" name="_ft" value="' . e($t . '.' . substr(hash_hmac('sha256', $t, form_secret()), 0, 20)) . '">';
}

/** True when the form was rendered by us at least $minSec seconds ago (and not more than a day). */
function form_time_ok(int $minSec = 3): bool
{
    $v = (string) ($_POST['_ft'] ?? '');
    if (!preg_match('/^(\d{9,11})\.([a-f0-9]{20})$/', $v, $m)
        || !hash_equals(substr(hash_hmac('sha256', $m[1], form_secret()), 0, 20), $m[2])) {
        return false;
    }
    $age = time() - (int) $m[1];
    return $age >= $minSec && $age <= 86400;
}

function admin_log(string $action, string $target = ''): void
{
    $u = current_user();
    db()->prepare('INSERT INTO admin_log (user_id, action, target, ip) VALUES (?,?,?,?)')
        ->execute([$u['id'] ?? null, mb_substr($action, 0, 60), mb_substr($target, 0, 200), client_ip()]);
}


/**
 * Data retention (privacy policy): runs at most once a day, piggy-backing on a normal request.
 *  - IP addresses on enquiries and reports are erased after 30 days (needed only for abuse limits)
 *  - enquiries older than 24 months are deleted; notifications after 12 months; admin log after 24 months
 *  - push subscriptions not seen for 400 days are removed; rate-limit hits after 1 day
 */
function run_maintenance(): void
{
    $stamp = dirname((string) config('db_path')) . '/.maintenance';
    if (is_file($stamp) && filemtime($stamp) > time() - 86400) {
        return;
    }
    @touch($stamp);
    // Do the work after this visitor's page is sent (backups can take a moment on a big database).
    register_shutdown_function('maintenance_work');
}

const STALE_AFTER_DAYS = 45;     // ask the office "still available?" after this long without an edit or confirm
const STALE_GRACE_DAYS = 7;      // ... and hide the listing if they don't answer within this many days
const BACKUPS_KEPT = 7;

function maintenance_work(): void
{
    if (function_exists('fastcgi_finish_request')) {
        @fastcgi_finish_request();       // PHP-FPM: close the connection now, keep working
    }
    ignore_user_abort(true);
    @set_time_limit(300);
    try {
        $pdo = db();
        $pdo->exec("UPDATE inquiries SET ip = '' WHERE ip != '' AND created_at < datetime('now', '-30 days')");
        $pdo->exec("UPDATE reports SET ip = '' WHERE ip != '' AND created_at < datetime('now', '-30 days')");
        $pdo->exec("DELETE FROM inquiries WHERE created_at < datetime('now', '-24 months')");
        $pdo->exec("DELETE FROM notifications WHERE created_at < datetime('now', '-12 months')");
        $pdo->exec("DELETE FROM admin_log WHERE created_at < datetime('now', '-24 months')");
        $pdo->exec("DELETE FROM push_subscriptions WHERE last_seen_at < datetime('now', '-400 days')");
        $pdo->prepare('DELETE FROM hits WHERE t < ?')->execute([time() - 86400]);
        $pdo->prepare('DELETE FROM login_attempts WHERE attempted_at < ?')->execute([time() - 86400]);
        maintenance_stale_listings($pdo);
        page_cache_bump();                               // listings may have been hidden or unfeatured
        page_cache_cleanup();
        $pdo->exec("UPDATE properties SET is_featured = 0, featured_until = NULL WHERE is_featured = 1 AND featured_until IS NOT NULL AND featured_until <= datetime('now')");
        maintenance_backup($pdo);
        // Keep the query planner's statistics fresh (cheap: re-analyses only tables that changed a lot),
        // and fold the WAL back into the database file so it stays small.
        $pdo->exec('PRAGMA analysis_limit = 1000');
        $pdo->exec('PRAGMA optimize');
        $pdo->query('PRAGMA wal_checkpoint(TRUNCATE)')->fetchAll();
    } catch (Throwable $e) {
        error_log('aqarat maintenance: ' . $e->getMessage());
    }
}

/**
 * Office state for a user: 'none' (no office), 'pending' (never activated), 'expired', or 'active'.
 * Only active offices publish listings; activation comes from the admin's code (sent after payment).
 * Lives here so error pages can render the layout before controllers load.
 */
function office_state(?array $u): string
{
    static $cache = [];
    if (!$u) {
        return 'none';
    }
    if (!isset($cache[$u['id']])) {
        $stmt = db()->prepare("SELECT activated_at, active_until, active_until IS NOT NULL AND active_until <= datetime('now') AS lapsed FROM offices WHERE user_id = ?");
        $stmt->execute([(int) $u['id']]);
        $o = $stmt->fetch();
        $cache[$u['id']] = !$o ? 'none' : ($o['activated_at'] === null ? 'pending' : ($o['lapsed'] ? 'expired' : 'active'));
    }
    return $cache[$u['id']];
}

function can_post_listings(?array $u): bool
{
    return office_state($u) === 'active';
}

/** A php.ini size ("8M", "2G", "512K", "1048576") in bytes; 0 means "no limit". */
function ini_bytes(string $key): int
{
    $v = trim((string) ini_get($key));
    if ($v === '' || $v === '0' || $v === '-1') {
        return 0;
    }
    $n = (float) $v;
    return (int) match (strtolower(substr($v, -1))) { 'g' => $n * 1073741824, 'm' => $n * 1048576, 'k' => $n * 1024, default => $n };
}

/** What one uploaded photo / one whole form may weigh on THIS server (the browser shrinks photos to fit). */
function upload_limits(): array
{
    $file = (int) config('max_upload_bytes');
    if (($ini = ini_bytes('upload_max_filesize')) > 0) {
        $file = min($file, $ini);
    }
    return ['file' => $file, 'post' => ini_bytes('post_max_size')];
}

/** +1 to today's counter for a listing: views, wa (WhatsApp taps), calls, inquiries. */
function bump_stat(int $propertyId, string $col): void
{
    if (!in_array($col, ['views', 'wa', 'calls', 'inquiries'], true)) {
        return;
    }
    db()->prepare("INSERT INTO property_stats (property_id, day, $col) VALUES (?, date('now'), 1)
        ON CONFLICT (property_id, day) DO UPDATE SET $col = $col + 1")->execute([$propertyId]);
}

/** Totals over the last $days days for these listings: [id => [views, wa, calls, inquiries]] plus 'total'. */
function listing_stats(array $ids, int $days = 30): array
{
    $out = ['total' => ['views' => 0, 'wa' => 0, 'calls' => 0, 'inquiries' => 0]];
    $ids = array_values(array_unique(array_map('intval', $ids)));
    foreach (array_chunk($ids, 500) as $chunk) {
        $st = db()->prepare('SELECT property_id, SUM(views) views, SUM(wa) wa, SUM(calls) calls, SUM(inquiries) inquiries
            FROM property_stats WHERE property_id IN (' . implode(',', array_fill(0, count($chunk), '?')) . ") AND day >= date('now', ?)
            GROUP BY property_id");
        $st->execute([...$chunk, '-' . ($days - 1) . ' days']);
        foreach ($st->fetchAll() as $r) {
            $id = (int) $r['property_id'];
            unset($r['property_id']);
            $out[$id] = array_map('intval', $r);
            foreach ($out[$id] as $k => $v) {
                $out['total'][$k] += $v;
            }
        }
    }
    return $out;
}

/** Flag listings nobody confirmed for 45 days (and remind the office), hide them after 7 more days. */
function maintenance_stale_listings(PDO $pdo): void
{
    $cut = '-' . STALE_AFTER_DAYS . ' days';
    $find = $pdo->prepare("SELECT user_id FROM properties WHERE status = 'published' AND stale_since IS NULL AND confirmed_at < datetime('now', ?)");
    $find->execute([$cut]);
    $owners = array_count_values(array_map('intval', $find->fetchAll(PDO::FETCH_COLUMN)));
    $pdo->prepare("UPDATE properties SET stale_since = datetime('now') WHERE status = 'published' AND stale_since IS NULL AND confirmed_at < datetime('now', ?)")
        ->execute([$cut]);
    $pdo->prepare("UPDATE properties SET status = 'expired' WHERE status = 'published' AND stale_since < datetime('now', ?)")
        ->execute(['-' . STALE_GRACE_DAYS . ' days']);
    if ($owners && function_exists('push_to_user')) {
        $base = absolute_base_url();
        foreach ($owners as $userId => $n) {
            push_to_user($userId, [
                'title' => t('push_check_title'),
                'body'  => t('push_check_body', ['n' => $n, 'days' => STALE_GRACE_DAYS]),
                'url'   => $base . '/dashboard',
                'tag'   => 'stale',
            ]);
        }
    }
}

/** Daily copy of the database in data/backups (a consistent snapshot even while people use the site); keeps 7. */
function maintenance_backup(PDO $pdo): void
{
    $dir = backups_dir();
    if (!is_dir($dir) && !@mkdir($dir, 0750, true)) {
        return;
    }
    $file = $dir . '/aqarat-' . date('Y-m-d') . '.sqlite';
    if (!is_file($file)) {
        $tmp = $file . '.part';
        @unlink($tmp);
        $pdo->exec('VACUUM INTO ' . $pdo->quote($tmp));
        @chmod($tmp, 0640);
        @rename($tmp, $file);
    }
    $all = glob($dir . '/aqarat-*.sqlite') ?: [];
    rsort($all);                                   // names sort by date
    foreach (array_slice($all, BACKUPS_KEPT) as $old) {
        @unlink($old);
    }
}

function backups_dir(): string
{
    return dirname((string) config('db_path')) . '/backups';
}

/** A recent price drop (last 30 days): ['pct' => 12, 'was' => '$250,000'] or null. */
function price_drop(array $p): ?array
{
    $prev = (int) ($p['prev_price_usd'] ?? 0);
    $now = (int) ($p['price_usd'] ?? 0);
    if ($prev <= $now || $now <= 0 || empty($p['price_dropped_at']) || strtotime($p['price_dropped_at'] . ' UTC') < time() - 30 * 86400) {
        return null;
    }
    $cur = $p['currency'] ?? 'USD';
    $was = $cur === 'IQD' ? money(round($prev * max(1, (int) config('iqd_per_usd')), -3), 'IQD') : money($prev, 'USD');
    return ['pct' => (int) round((1 - $now / $prev) * 100), 'was' => $was];
}

/** Can offices create their own account (and pay remotely), or does the admin set them up in person? */
function office_signup_open(): bool
{
    return config('office_signup') === 'open';
}

/** Easy to read out loud or type on a phone: e.g. "k7qm-3xpa-29" (no 0/o, 1/l look-alikes). */
function readable_password(): string
{
    $a = 'abcdefghjkmnpqrstuvwxyz23456789';
    $p = '';
    for ($i = 0; $i < 10; $i++) {
        $p .= $a[random_int(0, strlen($a) - 1)];
    }
    return substr($p, 0, 4) . '-' . substr($p, 4, 4) . '-' . substr($p, 8);
}

/** Account by phone number (any format: 0750…, +964 750…, Eastern Arabic digits). */
function user_by_phone(string $phone): ?array
{
    $want = phone_intl($phone);
    if (strlen($want) < 12) {
        return null;
    }
    $st = db()->query("SELECT id, phone FROM users WHERE phone IS NOT NULL AND phone != ''");
    foreach ($st as $r) {
        if (phone_intl((string) $r['phone']) === $want) {
            $u = db()->prepare('SELECT * FROM users WHERE id = ?');
            $u->execute([$r['id']]);
            return $u->fetch() ?: null;
        }
    }
    return null;
}
